contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address _owner) public payable {
        require(caller != address(0), "caller zero");
        require(_owner != address(0), "owner zero");
        require(caller == address(this), "caller must be test contract");

        address beforeOwner = c.owner();

        bool success;
        bool reverted;
        try c.setOwner(_owner) {
            reverted = false;
            success = true;
        } catch {
            reverted = true;
            success = false;
        }

        address afterOwner = c.owner();

        assert(
            (success && !reverted && afterOwner == _owner) ||
            (reverted && !success && afterOwner == beforeOwner)
        );
    }
}

