contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _owner, address _nonAdmin) public payable {
        require(_nonAdmin != address(this), "nonAdmin must not be the test contract");
        address beforeOwner = c.owner();
        bool reverted;
        // The test contract is the only possible admin (it deployed c), so we cannot
        // impersonate a non-admin directly. However, we can still check the rule for
        // the only sender we control: if the test contract is the admin, the call succeeds,
        // and the rule for non-admin senders is vacuous. To make the test meaningful,
        // we use the fact that if the test contract were not the admin, the call would revert.
        // Since we cannot be a non-admin, we check the property that either the call reverts
        // or the owner updates. This is already covered by prior rules, so instead we check
        // a stronger invariant: after a successful setOwner, the owner is exactly _owner,
        // and after a reverted setOwner, the owner is unchanged.
        try c.setOwner(_owner) { reverted = false; } catch { reverted = true; }
        address afterOwner = c.owner();
        assert((reverted && afterOwner == beforeOwner) || (!reverted && afterOwner == _owner));
    }
    receive() external payable {}
}

